<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Resources\PositionResource; use App\Models\Position; use App\Services\AuditLogService; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\AnonymousResourceCollection; use Illuminate\Http\Response;
class PositionController extends Controller { public function index(Request $r): AnonymousResourceCollection { return PositionResource::collection(Position::orderBy('name')->paginate($r->integer('per_page')?:100)); } public function store(Request $r): PositionResource { abort_unless($r->user()->hasPermission('hr.positions.manage'),403); $p=Position::create($this->data($r)); AuditLogService::log('hr','position_created',$p,null,$p->toArray(),$r); return new PositionResource($p); } public function update(Request $r, Position $position): PositionResource { abort_unless($r->user()->hasPermission('hr.positions.manage'),403); $old=$position->toArray(); $position->update($this->data($r,$position)); AuditLogService::log('hr','position_updated',$position,$old,$position->toArray(),$r); return new PositionResource($position); } public function destroy(Request $r, Position $position): Response { abort_unless($r->user()->hasPermission('hr.positions.manage'),403); $position->delete(); return response()->noContent(); } private function data(Request $r, ?Position $p=null): array { return $r->validate(['code'=>['required','string','max:100','unique:positions,code'.($p?','.$p->id:'')],'name'=>['required','string','max:255'],'category'=>['nullable','string','max:100'],'is_teaching_position'=>['boolean'],'is_active'=>['boolean']]); } }
